-- ============================================================
-- Migration 009: Assessment instrument v2 (versioning + v2 questions)
-- Task: plans/tasks/20261017-assessment-v2-questions-and-section-copy.md, Phase 4
--
-- RUN THIS BEFORE THE v2 CODE DEPLOYS. It is safe with today's (v1) code live:
--   * New columns all have defaults or are nullable. Today's code never names them,
--     so its inserts and selects behave exactly as before. Every existing session
--     and question becomes instrument_version = 1 through the default.
--   * v2 questions are NEW rows with NEW keys (all start with "V2"), inserted with
--     is_active = false. Today's code only ever loads questions with
--     is_active = true, or looks them up by v1 key (A001, A002, B001 to B004, Q074,
--     Q079, Q089, Q090), so it can't see a v2 row. No v1 row is edited.
--   * The workflow mode checks gain 'N' ("We don't do this work"). Widening a check
--     can't reject anything today's code writes.
--   * New sessions stay v1 until the v2 code is live: the column default is 1, and
--     only the v2 code writes instrument_version = 2.
--
-- After the v2 code is live it picks questions by instrument_version, not by
-- is_active, so a v1 session that was already in progress keeps its v1 questions
-- and scores exactly as before. Retiring v1 rows is a separate, optional step:
-- 010_instrument_v2_post_deploy.sql.
--
-- Re-runnable: columns use "if not exists", the mode checks are dropped and
-- re-added, and the question insert updates v2 rows in place on a second run
-- (it never touches is_active on a re-run, and never touches a v1 row).
--
-- The rows between the GENERATED markers come from scripts/v2-questions.mjs.
-- Edit wording there and run `node scripts/v2-questions.mjs`, never by hand here.
--
-- Run in Supabase Dashboard > SQL Editor.
-- ============================================================

begin;

-- 1. Version columns ---------------------------------------------------------

alter table questions
  add column if not exists instrument_version int not null default 1;

alter table assessment_sessions
  add column if not exists instrument_version int not null default 1;

-- A question only shown when another answer on the same page matches,
-- e.g. {"key": "V2B_C", "equals": "other_provider"} for the role box.
alter table questions add column if not exists show_if jsonb;

-- Alternate wording keyed by owner answer, e.g. {"each_agent": {"text": ..., "options": [...]}}
-- for workflows where "Each agent handles their own".
alter table questions add column if not exists variants jsonb;

create index if not exists idx_questions_version on questions(instrument_version, section);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'assessment_sessions_instrument_version_check') then
    alter table assessment_sessions
      add constraint assessment_sessions_instrument_version_check check (instrument_version in (1, 2));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'questions_instrument_version_check') then
    alter table questions
      add constraint questions_instrument_version_check check (instrument_version in (1, 2));
  end if;
end $$;

-- 2. Workflow mode 'N' = "We don't do this work" (v2 only) ---------------------

do $$
declare r record;
begin
  for r in
    select conname from pg_constraint
    where conrelid = 'assessment_sessions'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) ~ 'wf_[cdef]_mode'
  loop
    execute format('alter table assessment_sessions drop constraint %I', r.conname);
  end loop;
end $$;

alter table assessment_sessions add constraint assessment_sessions_wf_c_mode_check check (wf_c_mode in ('A','B','C','N'));
alter table assessment_sessions add constraint assessment_sessions_wf_d_mode_check check (wf_d_mode in ('A','B','C','N'));
alter table assessment_sessions add constraint assessment_sessions_wf_e_mode_check check (wf_e_mode in ('A','B','C','N'));
alter table assessment_sessions add constraint assessment_sessions_wf_f_mode_check check (wf_f_mode in ('A','B','C','N'));

-- 3. v2 questions (new rows, inactive to today's code) -----------------------

insert into questions (
  question_key, instrument_version, dimension_id, question_text, question_order, section,
  answer_type, is_scored, mode, oqi_dimension, drs_category, reverse_scored,
  applies_to_profile, weight, is_active, response_options, show_if, variants
) values
